def max_sum_after_rotations(matrix):
    n, m = len(matrix[0]), len(matrix)

    # Function to find the maximum of each row after applying rotations
    def max_over_all(v):
        res = [0] * m
        for i in range(m - 1, -1, -1):
            count = 0
            for j in range(1 << m):
                if count == 0 and j + i == m:
                    break
                if j + i < m:
                    count ^= (1 << j)
                else:
                    count ^= -1 << (count + m - j)
            res[m - count] = max(res[m - count], v[j])
        return sum(res)

    # Find the sum of the maximum after rotations for each row
    row_sums = list(map(max_over_all, zip(*matrix)))

    # The maximum sum is the total sum minus the minimum sum
    return sum([a*n - min(row_sums) for a in row_sums])

