import math
from functools import lru_cache

def gcd(a, b):
    return a if b == 0 else gcd(b, a % b)

def calculate_time(judges, skills, clients):
    @lru_cache(maxsize=None)
    def helper(cur_skill, experienced_clients):
        if not clients:
            return cur_skill
        max_gcd = 0
        total_time = float('inf')
        for idx in range(len(clients)):
            if experienced_clients & (1 << idx) == 0:
                divided_uncertainty = gcd(cur_skill, clients[idx]) if cur_skill and clients[idx] else cur_skill
                new_skill = divided_uncertainty
                new_exprefences = experienced_clients | (1 << idx)
                if new_skill < 1:
                    continue
                time_used = new_skill * experienced_clients
                time_used = time_used if time_used != float('inf') and new_skill != float('inf') else -1
                next_time = helper(new_skill, new_exprefences)
                if next_time == -1:
                    break
                time_used = min(time_used, next_time)
                max_gcd = max(gcd(max_gcd, new_skill), 1)
                if time_used == -1:
                    break
                if time_used > float('inf'):
                    break
                total_time = min(total_time, time_used + max_gcd)
        return total_time

    optimal_skill, optimal_time = math.inf, -1
    value = 0
    for idx in range(len(judges)):
        if experienced_clients & (1 << idx) == 0:
            value += judges[idx]
    optimal_skill = value
    optimal_time = helper(optimal_skill, 0)

    if optimal_time < 0:
        return -1
    return optimal_time
