# Function to determine Alice's scenario
def alice_can_win(n, m, a, b, c):
    # Initialize cost matrix
    cost = [[c[i][j] for j in range(m)] for i in range(n)]
    # Function to calculate maximum profit for any combination of locks
    def max_profit(a, b, c):
        dp = [[-1 for _ in range(sum(b)+1)] for _ in range(len(a)+1)]
        dp[0][0] = 0
        for i in range(1, len(a)+1):
            for j in range(sum(b)+1):
                if a[i-1] <= j:
                    # max profit includes or excludes the current chest
                    dp[i][j] = max(dp[i-1][j], dp[i-1][j-a[i-1]] + a[i-1])
                else:
                    dp[i][j] = dp[i-1][j]
        # Ensure Bob cannot get positive profit
        for i in range(len(a)+1):
            if b[i] > 0 and dp[len(a)][b[i]] > 0:
                return False
        return max_profit(dp)

    # Case I: If any key can only let open one chest
    if any(b[j] == 1 for j in range(m)):
        # This case means Alice cannot choose if she puts lock at which j-th chest
        #  thus she can always buy all key so any combination of keys earn her profit
        return 0

    # Otherwise, spend money on those locked chests so that coins in opened chests > cost to open keys
    # Least profit if she can cover everything by those locks
    if max_profit(a, b, cost):
        return min(sum(cost[i][j] * b[j] for i in range(n) if b[j]) for j in range(m))
    else:
        return -1

