from collections import defaultdict

def find_max_suspect(sub_string, sus, not_appended):
    max_value = -1
    i = 0
    while i < len(sub_string):
        if sub_string[i] not in not_appended:
            i += 1
        else:
            max_value = max(max_value, sus[sub_string[i]])
            i += 1
    return max_value

def manage_database(entries, n, queries):
    db = defaultdict(int)
    for i, name in enumerate(entries):
        db[name] = i
    for query in queries:
        action, index, value = query.split()
        index = int(index) - 1
        if action == '1':
            db[entries[index]] = db[entries[index]] - value + value
            db[entries[index]] -= value
            value = (value + 1) * (value + 1)
            for i in range(max(index - 10, 0), index + 10):
                if i >= 0:
                    db[entries[i]] = db[entries[i]] + value
        else:
            if index == len(entries) and len(entries) > 0:
                db.pop(entries[-1])
                entries.pop()
                continue
            search_space = range(index, len(entries))
            likely_suspect = -1
            for start_idx in search_space:
                for end_idx in range(start_idx + 1, len(entries)):
                    probable_name = entries[start_idx:end_idx]
                    current_suspect = find_max_suspect(probable_name, db[start_idx:end_idx + 1], {name: db[name] for name in entries[start_idx:end_idx + 1]})
                    if current_suspect == -1:
                        break
                    if current_suspect > likely_suspect:
                        likely_suspect = current_suspect
            else:
                if likely_suspect == -1:
                    continue
                db[entries[-1]] = max(db[entries[-1]], likely_suspect)
    return db

