def find_min_order_statistic(n, s, m, k, a, segments):
    segment_to_indices = defaultdict(list)
    for seg in segments:
        segment_to_indices[seg[0]].append(seg)

    if k > n or (m + k - 1 > s):
        return -1

    if m == 0 and k == 1:
        return a[0]

    if k == 1:
        return min(a)

