from heapq import heappush, heappop

def find_minimal_set_weights(n, m):
    seen = set()
    max_bag_weight = m
    a = [i for i in range(1, n+1)]
    heap = [v for v in a]

    while True:
        if len(heap) == n:
            break

        max_bag_weight = max(max_bag_weight, heap[0])
        ls = []
        for i in range(len(heap) - 1, -1, -1):
            if heap[i] == max_bag_weight:
                ls.append((heap[i], i))
                heappop(heap)
                if len(heap) < len(ls):
                    break
        for x,y in ls:
            heappush(heap, x - y)

    p = [x for x,y in ls]
    if len(ls) < n:
        return "NO"
    else:
        return "YES\n" + str(len(p)) + '\n' + ' '.join(map(str,p))

