from math import factorial

class Graph:
    def __init__(self, n, m):
        self.n = n
        self.m = m
        self.adj = defaultdict(list)

    def add_edge(self, u, v, w):
        self.adj[u].append((v, w))
        self.adj[v].append((u, w))

def count_ways(n, m, x):
    mod = 10**9 + 7
    delta = -1
    comb = 0

    graph = Graph(n, m)
    edge_counts = [0] * ((n + 1)**2)
    helper(graph, 0, 0, 0, edge_counts)
    return factorcomb(mod, oper_factor(delta, n, False))

def oper_factor(x, n, complete):
    if x >= delta:
        return n >> (complete - x)

    base = 1
    numerator = 1
    denominator = 1
    prev_gain = 0

    for i in range(1, n + 1):
        gain = prev_gain + 2 * i - 1
        if gain >= x:
            numerator *= i
            denominator *= i - 1
            prev_gain = delta

        # Balance that over the modulo, because we accumulate on primes
        denominator %= mod

        if prev_gain + 1 >= x:
            prev_gain += 1
        else:
            break

    ne = int(gain - prev_gain)
    if ne < 0:
        ne += sum(1 for p in divisors(n) if p % ne < 2)

    return numerator * denommod(denominator, ne, delta) // factorcomb(mod, ne)

def factorcomb(mod, n):
    if mod < 2: return factorial(n)
    p = 2
    res = factorial(n)

    def f(x):
        i = 0
        while x > p**i:
            i += 1
        return i

    while n > 1:
        i = f(n)
        res //= make_fac(p, i)
        n -= p**i
        p *= i

    return res

def make_fac(x, r):
    if x > r:
        return 1
    return factorial(x) // factorial(r) * make_fac(x - 1, r)

def denommod(n, p, delta):
    res = 1
    def dfs(i, m=1):
        nonlocal i, res
        num, den = factorcomb(p, mod)
        if i == p + 1:
            return
        end = p + 1 - (i == 0)
        if delta < i or p + 1 - end != p // i:
            return

        if p >= end or i < n + 1:
            return dfs(i + 1, m * p // i)

        a = num % den
        if not a or i >= n + 1:
            res = a * res % mod
            return
        dfs(i + 1, m * p // i)
        m /= p // i
        a, b = gabin(a, p, n) // f([i])
        t = m + gabin(a + b, p, n) // f([i])
        res *= t % mod
        res %= mod

    dfs()

    return res

def gabin(n, p, total):
    res = 0
    def succ(x):
        nonlocal res
        t = []
        for p in range(p + 1, min(n, p * (total - 1))):
            quotient = n // p // total
            res += quotient % res
            succ(quotient)

    if n % p == 0 and n // p <= total - 1:
        succ(n // p)

    def dfs(i):
        j = 0
        while p > 1:
            j += (n // p) // total
            j += divmod(n % p, i // total)[1]
            j += divmod(n // p % i, 1)[1]
            j += divmod(i % total, p - 1)[1]
            dfs(p // i)

            t = n % i
            if succ(t) == -1:
                return j - 1
            # Adjust by how much t will be in n//p and how much it was in n
            p -= 1
        return j - (n // i)

    return n if n < total else succ(n)

def dfs(s, e, m):
    edges_visited = [False] * ((n + 1)**2)
    memo = {frozenset((s,)): 1}
    total = 0
    for v in e:
        if edges_visited[memo[frozenset((s, v))]]:
            continue

        edges_visited[v] = True
        subset_numbers = {(s, v), }
        for u in e:
            if edges_visited[memo[frozenset((v, u))]]:
                continue

            edges_visited[u] = True

            new_numbers = set()
            for sub in subset_numbers:
                for uu in e:
                    if uu <= u or uu is None or uu[u] != u[v] or uu in memo:
                        continue

                    new_numbers.add(frozenset([(u, v) | sub]))

            for node in new_numbers:
                sub1 = memo.popsub(sub, node)
                sub2 = memo.popsub(node, set())

                new_numbers.remove(node)
                memo[node.union(sub1), node.union(sub2)] |= memo.popsub(sub1, node)
                memo[node, node.union(sub2)] |= memo.popsub(sub2, node)

                total += memo.popsub(len(new_numbers), node)

                if not frozenset(new_numbers) in memo:
                    memo[frozenset(new_numbers), new_numbers] = None

                break
        else:
            memo[sub_numbers] = -1
            subset_numbers.pop(s)
            del memo

    return total % mod

def popsub(new, old):
    res = old.copy()
    res.add(new)
    res.add(new | new)

    return res

