from typing import List
from typing import Tuple
from typing import Dict
from typing import Set

def select_segments(n: int, s: int, m: int, k: int, a: List[int]) -> int:
    cover_threshold = pow(2, k - 1)
    segment_coverage: Dict[int, Set[int]] = {i: set() for i in range(n)}

    for l, r in zip(*[iter([a[i] for i in range(n)])] * 2):
        if r - l + 1 <= cover_threshold:
            for i in range(l, r + 1):
                segment_coverage[i].add(l)

    ordered_segments: List[int] = sorted(segment_coverage.keys())
    leftmost_segment_index = 0
    segmented_hit_count: int = 0

    for segment in ordered_segments:
        if influenced_segment_coverage := any(segment_coverage[seg] for seg in segment_coverage[segment]):
            segmented_hit_count += 1
            leftmost_segment_index += 1

    if segmented_hit_count < m:
        return -1

    return n - (m - segmented_hit_count + leftmost_segment_index)
