import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def find_min_time(n, k, a, e):
    min_seconds = n + 1
    for judge in range(n):
        if gcd(a[judge], k) == 1:
            if judge == n - 1:
                min_seconds = min(min_seconds, n * e[n-1])
            else:
                for ep in range(1, k // a[judge] + 1):
                    time = (ep * e[judge] + (n - judge - 1) * e[n-1]) / (ep + 1) ** 2
                    if time < min_seconds:
                        min_seconds = time
    return min_seconds if min_seconds < n + 1 else -1

