from collections import defaultdict

def can_satisfy_flows(n, flows, pipes):
    adj = defaultdict(list)
    in_degree = [0] * (n + 1)
    out_degree = [0] * (n + 1)

    for x, y in pipes:
        adj[x].append(y)
        adj[y].append(x)
        in_degree[y] += 1
        out_degree[x] += 1

    max_flow = 0
    queue = [x for x, indegree in enumerate(out_degree) if not indegree]
    while queue:
        node = queue.pop(0)
        if flows[node] == 0:
            check = None
            for adj_node in adj[node]:
                if out_degree[adj_node] > 0:
                    check = adj_node
                    break
            if check is None:
                continue
            if out_degree[node] > in_degree[check]:
                in_degree[check] += out_degree[node]
                out_degree[node] = 0
                max_flow += 1
            else:
                in_degree[node] -= out_degree[node]
                out_degree[node] = 0
                max_flow += out_degree[node]
        else:
            flows[node] -= 1

    for i in range(1, n + 1):
        if in_degree[i] != flows[i] or out_degree[i] != -flows[i]:
            return "Impossible"

    return "Possible"

