from math import gcd

def lcm(x, y):
    """Return lowest common multiple of x and y."""
    return x * y // gcd(x, y)

def points_on_circle(radius):
    """Generate all integer points on or within the circle of radius 'radius' centered at the origin."""
    radius_squared = radius ** 2
    for x in range(-radius, radius + 1):
        for y in range(-radius, radius + 1):
            if x**2 + y**2 <= radius_squared:
                yield (x, y)

def area_of_intersection(a, b):
    """Calculate the area of intersection of two circles whose centers are at a distance r."""
    radius_sum = (abs(a[0] - b[0]) + abs(a[1] - b[1])) / 2
    radius_diff_sq = (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2
    max_radius = max(radius_sum, radius_diff_sq**0.5)
    min_radius = min(radius_sum, radius_diff_sq**0.5)
    if radius_diff_sq < max_radius ** 2:
        return radius_diff_sq
    top = (min_radius ** 2) * 2
    bottom = ((min_radius ** 2) - (max_radius ** 2) - (2) * max_radius * radius_diff_sq) ** (0.5)
    return top / radius_diff_sq - bottom / radius_diff_sq

def find_optimal_tower_positions(radius, n):
    """Find the optimal positions for n towers on the plane such that the sum of squared distances is maximized."""
    max_area = 0
    best_positions = []
    points = points_on_circle(radius)
    for i in range(n):
        for j in range(i, n):
            a, b = points[i], points[j]
            area = area_of_intersection(a, b)
            if area > max_area:
                max_area, best_positions = area, [a, b]
    if len(best_positions) <= 2:
        nearest_positions = sorted(points)
        for i in range(n):
            for j in range(i + 1, min(i + 4, len(points)), 1):
                a, b = best_positions[i], nearest_positions[j]
                area = area_of_intersection(a, b)
                if area > max_area:
                    max_area, best_positions = area, [a, b, nearest_positions[j]]
    return max_area

def get_tower_positions(radius, n):
    """Find the optimal positions for n towers and return them."""
    max_area = find_optimal_tower_positions(radius, n)
    areas = []
    segments = []
    for i in range(1, n + 1):
        for j in range(i, n + 1):
            area = area_of_intersection(tower_positions[i], tower_positions[j])
            areas.append(area)
            segments.append((area, i, j))
    segments.sort()
    max_areas = segments[:n//2]
    reel_max_area = max_areas[-n//2][0]
    max_positions = []
    for area, seg in max_areas:
        if area > reel_max_area:
            reel_max_area = area
            max_positions = [tower_positions[key] for key in seg]
    return max_areas, max_positions

