import sys

def find_min_crossing_points(polygon1, polygon2):
    x_min1, y_min1, z_min1 = float('inf'), float('inf'), float('inf')
    x_max1, y_max1, z_max1 = float('-inf'), float('-inf'), float('-inf')
    x_min2, y_min2, z_min2 = float('inf'), float('inf'), float('inf')
    x_max2, y_max2, z_max2 = float('-inf'), float('-inf'), float('-inf')

    for i in range(len(polygon1)):
        x_min1 = min(x_min1, min(polygon1[i-1][0], polygon1[i][0]))
        y_min1 = min(y_min1, min(polygon1[i-1][1], polygon1[i][1]))
        x_max1 = max(x_max1, max(polygon1[i-1][0], polygon1[i][0]))
        y_max1 = max(y_max1, max(polygon1[i-1][1], polygon1[i][1]))
        for j in range(len(polygon2)):
            x_min2 = min(x_min2, min(polygon2[j][0], polygon2[j+1][0]))
            y_min2 = min(y_min2, min(polygon2[j][1], polygon2[j+1][1]))
            x_max2 = max(x_max2, max(polygon2[j][0], polygon2[j+1][0]))
            y_max2 = max(y_max2, max(polygon2[j][1], polygon2[j+1][1]))

    crossing_points1 = []
    for i in range(len(polygon1)):
        if polygon1[i][0] >= x_min2 and polygon1[i][0] <= x_max2:
            crossing_points1.append((max(polygon1[i][1], polygon1[(i+1) % len(polygon1)][1]), max(polygon1[i][2], polygon1[(i+1) % len(polygon1)][2])))
        if polygon1[i][1] >= y_min2 and polygon1[i][1] <= y_max2:
            crossing_points1.append((max(polygon1[i][0], polygon1[(i+1) % len(polygon1)][0]), max(polygon1[i][2], polygon1[(i+1) % len(polygon1)][2])))
        if polygon1[i][2] >= z_min2 and polygon1[i][2] <= z_max2:
            crossing_points1.append((max(polygon1[i][0], polygon1[(i+1) % len(polygon1)][0]), max(polygon1[i][1], polygon1[(i+1) % len(polygon1)][1])))
        if polygon1[i][0] == polygon1[(i+1) % len(polygon1)][0] and polygon1[i][1] < polygon1[(i+1) % len(polygon1)][1]:
            crossing_points1.append((min(polygon1[i][0], polygon1[(i+1) % len(polygon1)][0]), polygon1[i][1]))

    crossing_points2 = []
    for i in range(len(polygon2)):
        if polygon2[i][0] >= x_min1 and polygon2[i][0] <= x_max1:
            crossing_points2.append((max(polygon2[i][1], polygon2[(i+1) % len(polygon2)][1]), max(polygon2[i][2], polygon2[(i+1) % len(polygon2)][2])))
        if polygon2[i][1] >= y_min1 and polygon2[i][1] <= y_max1:
            crossing_points2.append((max(polygon2[i][0], polygon2[(i+1) % len(polygon2)][0]), max(polygon2[i][2], polygon2[(i+1) % len(polygon2)][2])))
        if polygon2[i][2] >= z_min1 and polygon2[i][2] <= z_max1:
            crossing_points2.append((max(polygon2[i][0], polygon2[(i+1) % len(polygon2)][0]), max(polygon2[i][1], polygon2[(i+1) % len(polygon2)][1])))
        if polygon2[i][0] == polygon2[(i+1) % len(polygon2)][0] and polygon2[i][1] < polygon2[(i+1) % len(polygon2)][1]:
            crossing_points2.append((min(polygon2[i][0], polygon2[(i+1) % len(polygon2)][0]), polygon2[i][1]))

    return len(crossing_points1), len(crossing_points2), set(crossing_points1).intersection(crossing_points2)

def is_well_connected(n, polygon1, m, polygon2):
    if n % 2 != 0 or m % 2 != 0:
        return "NO"

    for i in range(n):
        if polygon1[i][0] != polygon1[(i+1) % n][0] and polygon1[i][1] != polygon1[i+1][1]:
            return "NO"

    for i in range(m):
        if polygon2[i][0] != polygon2[(i+1) % m][0] and polygon2[i][1] != polygon2[i+1][1]:
            return "NO"

    min_crossings, max_crossings, crossing_points_full = find_min_crossing_points(polygon1, polygon2)
    if min_crossings * 2 != max_crossings:
        return "NO"

    for i in range(len(crossing_points_full)):
        min_x = min(crossing_points_full[i])
        max_x = max(crossing_points_full[i])
        min_y = min(min(crossing_points_full[:i]), min(crossing_points_full[i+1:]))
        max_y = max(max(crossing_points_full[:i]), max(crossing_points_full[i+1:]))
        if min_x >= min_y or max_x <= max_y:
            return "NO"

    return "YES"

