import heapq

def play(toys, children_playing):
    toys heapq.heapify(toys)
    while toys:
        toy = toys[0]
        for i, child in enumerate(children_playing):
            if child == toy:
                heapq.heapreplace(toys, child)
                del children_playing[i]
                break
        else:
            children_playing.append(toy)

def query(scenario, query):
    toys = []
    children_playing = []
    for t in scenario + [query]:
        if t[0] not in children_playing:
            play(toys, [(t[1], v) for v in children_playing if v not in t[0]])
            heapq.heappush(toys, t[1])
        children_playing.append(t[1])
    return len(list(filter(lambda x: x == 0, toys)))

