def max_dist_sum(n: int, r: int) -> int:
    max_sum = 0
    towers = []

    def is_valid(x: int, y: int, r: int) -> bool:
        for (a, b) in towers:
            if ((x - a) ** 2 + (y - b) ** 2) <= r ** 2:
                return False
        return True

    for x in range(-r, r + 1):
        for y in range(-r, r + 1):
            if is_valid(x, y, r):
                towers.append((x, y))
                max_sum += (x ** 2 + y ** 2)
                break
    return max_sum, towers

